/*
 * A041386  Numerators of continued fraction convergents to sqrt(208).
 * https://oeis.org/A041386
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   a(n) = numerator of the n-th convergent in the continued
 *            fraction expansion of sqrt(208). This is obtained by the
 *            standard recurrence for continued–fraction convergents: p_{-1} =
 *            1, p_{-2} = 0 p_k = a_k * p_{k-1} + p_{k-2} with the partial
 *            quotients a_k generated by the algorithm for sqrt(208). T...
 * Range:     u8 n <= 3, u16 n <= 7, u32 n <= 17, u64 n <= 35, u128 n <= 72,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* continued‑fraction data for sqrt(208) */
    unsigned long long m = 0;          /* m_k */
    unsigned long long d = 1;          /* d_k */
    unsigned long long q = 14;         /* a_k (partial quotient) */

    /* convergent numerators  p_{-1} = 1,  p_{-2} = 0  */
    seq_t p_prev = 1;  /* p_{k-1}  (starts as p_{-1}) */
    seq_t p_prev2 = 0; /* p_{k-2}  (starts as p_{-2}) */
    seq_t p_k      = 0;/* current numerator */

    /* iterate until we reach the requested index */
    for (idx_t i = 0; i <= n; ++i)
    {
        /* compute p_k = q * p_{k-1} + p_{k-2} */
        p_k = q * p_prev + p_prev2;

        /* shift for next step */
        p_prev2 = p_prev;
        p_prev  = p_k;

        /* generate next partial quotient a_{k+1} */
        unsigned long long m_next = d * q - m;
        unsigned long long d_next = (208ULL - m_next * m_next) / d;
        unsigned long long q_next = (14ULL + m_next) / d_next;

        /* advance state */
        m = m_next;
        d = d_next;
        q = q_next;
    }

    return p_k;
}
